plugins {
    id("com.android.application")
    id("com.google.gms.google-services")
}

// -Ptbd.werror=true (scripts/test-android.sh) turns every Kotlin compiler warning into an error.
val werror = providers.gradleProperty("tbd.werror").map(String::toBoolean).orElse(false)
// The shared protocol test vectors, generated by the Go side (`mise run gen-vectors`).
val protoVectors = rootProject.layout.projectDirectory.file("../proto/vectors.json")

// Version from the release tag (scripts/version.sh, passed as -Ptbd.versionCode/-Ptbd.versionName by
// scripts/build-android.sh); a plain local build is the development version 1 / 0.0.0-dev.
val tbdVersionCode = providers.gradleProperty("tbd.versionCode").map(String::toInt).orElse(1)
val tbdVersionName = providers.gradleProperty("tbd.versionName").orElse("0.0.0-dev")

// Release signing (D23) comes from the environment only, never from a file in the repository:
// TBD_RELEASE_KEYSTORE (path to the PKCS12 keystore), TBD_RELEASE_KEYSTORE_PASSWORD (store and key
// password), TBD_RELEASE_KEY_ALIAS (default teams-bridge), TBD_RELEASE_KEY_PASSWORD (default: the
// store password). Without TBD_RELEASE_KEYSTORE the release APK is unsigned (app-release-unsigned.apk).
// scripts/build-android.sh runs signed builds without the configuration cache and the daemon, so the
// password is neither stored in a cache entry nor kept by a long-lived JVM.
val releaseKeystore = providers.environmentVariable("TBD_RELEASE_KEYSTORE").orNull?.takeIf { it.isNotEmpty() }

android {
    namespace = "io.github.alien2003.teamsbridge"
    // Keep in sync with PACKAGES in scripts/android-sdk.sh.
    compileSdk {
        version = release(37) { minorApiLevel = 2 }
    }
    buildToolsVersion = "37.0.0"

    defaultConfig {
        applicationId = "io.github.alien2003.teamsbridge"
        minSdk = 28
        targetSdk = 37
        versionCode = tbdVersionCode.get()
        versionName = tbdVersionName.get()
    }

    signingConfigs {
        // Project-local debug key (scripts/debug-keystore.sh), never ~/.android/debug.keystore.
        getByName("debug") {
            storeFile = rootProject.file("../.tools/debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
        if (releaseKeystore != null) {
            create("release") {
                val password = providers.environmentVariable("TBD_RELEASE_KEYSTORE_PASSWORD").orNull
                    ?.takeIf { it.isNotEmpty() }
                    ?: throw GradleException("TBD_RELEASE_KEYSTORE is set but TBD_RELEASE_KEYSTORE_PASSWORD is not")
                val keystore = file(releaseKeystore)
                if (!keystore.isFile) throw GradleException("TBD_RELEASE_KEYSTORE: no such file: $keystore")
                storeFile = keystore
                storeType = "pkcs12"
                storePassword = password
                keyAlias = providers.environmentVariable("TBD_RELEASE_KEY_ALIAS").orNull?.takeIf { it.isNotEmpty() } ?: "teams-bridge"
                keyPassword = providers.environmentVariable("TBD_RELEASE_KEY_PASSWORD").orNull?.takeIf { it.isNotEmpty() } ?: password
                // minSdk 28 needs no v1 (JAR) signature; v3 next to v2 allows a later key rotation.
                enableV1Signing = false
                enableV2Signing = true
                enableV3Signing = true
            }
        }
    }

    buildTypes {
        // Both build types run R8: unminified, the debug dex alone is ~18 MB, far over the 6 MB limit
        // of BRIEF §6. For a debuggable build R8 only shrinks (no optimisation, no obfuscation), so
        // stack traces and debugging stay readable. Release also optimises and obfuscates; its
        // mapping.txt ships with every GitHub release (teams-bridge-mapping.txt.gz, D23).
        debug {
            signingConfig = signingConfigs.getByName("debug")
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
        }
        release {
            signingConfig = signingConfigs.findByName("release")
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro", "proguard-release.pro")
        }
    }

    // No "dependency metadata" block: it is encrypted with a key of Google's, so nobody else can read
    // it, and F-Droid-style scanners flag it.
    dependenciesInfo {
        includeInApk = false
        includeInBundle = false
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    androidResources {
        // The UI is English only; drop the translations that Material, AppCompat, Play services and
        // zxing bring along (a large part of the APK otherwise).
        localeFilters += "en"
    }

    packaging {
        // AGP stores dex uncompressed for minSdk >= 28 (mmap-able, but ~2x larger APK). Compressed
        // dex keeps the debug APK at about half the 6 MB budget; ART compiles it at install anyway.
        dex {
            useLegacyPackaging = true
        }
        // DataStore's prebuilt (already stripped) helper; without an NDK AGP cannot strip it and says so.
        jniLibs {
            keepDebugSymbols += "**/libdatastore_shared_counter.so"
        }
        resources {
            excludes += setOf(
                "META-INF/*.version",
                "META-INF/**/LICENSE*",
                "META-INF/**/NOTICE*",
                "kotlin/**",
                "DebugProbesKt.bin",
            )
        }
    }

    testOptions {
        unitTests.all { test ->
            test.systemProperty("tbd.vectors", protoVectors.asFile.absolutePath)
            test.inputs.file(protoVectors).withPathSensitivity(PathSensitivity.NONE).withPropertyName("protoVectors")
        }
    }
}

kotlin {
    compilerOptions {
        allWarningsAsErrors.set(werror)
    }
}

dependencies {
    // BRIEF §6 list only; versions and sources in docs/DECISIONS.md.
    implementation(platform("com.google.firebase:firebase-bom:35.1.0"))
    implementation("com.google.firebase:firebase-messaging")
    implementation("com.journeyapps:zxing-android-embedded:4.3.0")
    // work-runtime-ktx is an empty alias since WorkManager 2.10; the Kotlin API lives in work-runtime.
    implementation("androidx.work:work-runtime:2.12.0")
    implementation("com.google.android.material:material:1.14.0")

    testImplementation("junit:junit:4.13.2")
    // android.jar's org.json is a stub ("Stub!") on the JVM; the real library runs the parser in tests.
    testImplementation("org.json:json:20260814")
}
